import { defineTool as defineTool5 } from "npm:@lovable.dev/mcp-js@0.25.0";
import { z as z4 } from "npm:zod@^3.25.76";
var create_transaction_default = defineTool5({
  name: "create_transaction",
  title: "Criar lan\xE7amento",
  description: "Cria um lan\xE7amento (receita ou despesa) no FinZap para o m\xEAs correspondente \xE0 data informada. O m\xEAs precisa existir e n\xE3o estar fechado.",
  inputSchema: {
    name: z4.string().describe("Descri\xE7\xE3o curta do lan\xE7amento."),
    amount: z4.number().describe("Valor em reais, sempre positivo."),
    type: z4.enum(["income", "expense"]).describe("Receita (income) ou despesa (expense)."),
    date: z4.string().describe("Data do lan\xE7amento no formato AAAA-MM-DD."),
    category: z4.string().optional().describe("Categoria do lan\xE7amento.")
  },
  annotations: { readOnlyHint: false, destructiveHint: false, openWorldHint: false },
  handler: async ({ name, amount, type, date, category }, ctx) => {
    if (!ctx.isAuthenticated()) return notAuthenticated;
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date))
      return { content: [{ type: "text", text: "Data inv\xE1lida. Use AAAA-MM-DD." }], isError: true };
    if (!(amount > 0))
      return { content: [{ type: "text", text: "O valor deve ser maior que zero." }], isError: true };
    const supabase = supabaseForUser(ctx);
    const year = Number(date.slice(0, 4));
    const month = Number(date.slice(5, 7));
    const { data: m, error: mErr } = await supabase.from("months").select("id, status").eq("year", year).eq("month", month).maybeSingle();
    if (mErr) return { content: [{ type: "text", text: mErr.message }], isError: true };
    if (!m)
      return {
        content: [{ type: "text", text: `O m\xEAs ${month}/${year} ainda n\xE3o existe no FinZap.` }],
        isError: true
      };
    if (m.status === "closed")
      return {
        content: [{ type: "text", text: `O m\xEAs ${month}/${year} est\xE1 fechado.` }],
        isError: true
      };
    const { data, error } = await supabase.from("transactions").insert({
      user_id: ctx.getUserId(),
      month_id: m.id,
      name: name.trim(),
      amount,
      type,
      date,
      category: category ?? null
    }).select("id, name, amount, type, date, category").single();
    if (error) return { content: [{ type: "text", text: error.message }], isError: true };
    return {
      content: [
        {
          type: "text",
          text: `Lan\xE7amento criado: ${data.name} \u2014 ${brl(Number(data.amount))} (${type === "income" ? "receita" : "despesa"}) em ${data.date}.`
        }
      ],
      structuredContent: { transaction: data }
    };
  }
});

